RED.causeway= ( function(){
    var dialog;
    var dialogContainer;
    var exportcausewayNodesDialog;
    var importTypewlNodesDialog;
    var activeTab;
    var libraryBrowser;
    var disabled = false;

    // DataStructures for causeway
    var causeway_schema_dict = {}
    let data_schema_causeway = {}
    let _labels = {}
    var model_name ;
    function showCausewayExportDialog()
    {
        dialogContainer.empty();
        dialogContainer.append($(exportCausewayDialog));
        var tabs = RED.tabs.create({
            id: "red-ui-causeway-dialog-export-tabs",
            vertical: true,
            onchange: function(tab) {
                $("#red-ui-causeway-dialog-export-tabs-content").children().hide();
                $("#" + tab.id).show();
                activeTab = tab.id;
                if (tab.id === "red-ui-causeway-dialog-export-tab-causeway-clipboard") {
                    $("#red-ui-causeway-dialog-export").button("option","label", "Copy").show()
                    $("#red-ui-causeway-dialog-download").show();
                    $("#red-ui-causeway-dialog-deploy").show()
                }
                else if(tab.id === "red-ui-causeway-dialog-export-tab-causeway-deploy")
                {
                    $("#red-ui-causeway-dialog-deploy").show()
                    $("#red-ui-causeway-dialog-export").hide()
                    $("#red-ui-causeway-dialog-download").hide();
                } else {
                    $("#red-ui-causeway-dialog-export").button("option","label", "Copy").show()
                    $("#red-ui-causeway-dialog-download").hide();
                    $("#red-ui-causeway-dialog-deploy").hide()
                }
            }
        });

        tabs.addTab({
            id: "red-ui-causeway-dialog-export-tab-causeway-clipboard",
            label: "Causal Analysis"
        });

        $("#red-ui-causeway-dialog-export").button("enable");

        dialogContainer.i18n();
        var format = RED.settings.flowFilePretty ? "red-ui-clipboard-dialog-export-fmt-full" : "red-ui-clipboard-dialog-export-fmt-mini";
        var activeWorkspace = RED.workspaces.active();
        var parentNode = RED.nodes.workspace(activeWorkspace)||RED.nodes.subflow(activeWorkspace) || RED.nodes.submodel(activeWorkspace);


        model_name = parentNode.label

        // get all nodes in the graph
        var nodes = null
        nodes = RED.nodes.groups(activeWorkspace)
        nodes = nodes.concat(RED.nodes.filterNodes({z:activeWorkspace}))
        nodes.unshift(parentNode)
        nodes = RED.nodes.createExportableNodeSet(nodes)

        // [v]:Entity Node Id ; [vt]: Graph Id
        let data_graphs = {}
        nodes.forEach( node=>{
            if(node.props){
                node.props.forEach( prop=>{
                    if(prop.p === "input"){
                        if(!data_graphs[prop.vt]){
                            let type_init = {[prop.v]: [node.name]}
                            data_graphs = {...data_graphs, [prop.vt]:type_init}
                        }else{
                            let kg_nodes = data_graphs[prop.vt]
                            if(kg_nodes[prop.v]){
                                let type_updates = kg_nodes[prop.v]
                                type_updates.push(node.name)
                                data_graphs ={...data_graphs, [prop.vt]: { ...data_graphs[prop.vt], [prop.v]:type_updates}}
                            }
                        }
                    }
                })
            }
        })

        // console.log("[OBJECT] Data graphs : ", data_graphs)
        Object.keys(data_graphs).forEach(key=>{
            // console.log("\tgraph key: ", key)
            let parent = RED.nodes.workspace(key)
            if(parent){ 
                _labels[parent.label] = {}
                if(data_graphs[key]){
                    Object.keys(data_graphs[key]).forEach( node_key=>{
                        let node = RED.nodes.node(node_key)
                        _labels[parent.label][node.name]= data_graphs[key][node_key]
                    })

                }
            }
            // console.log("\t\tparent: ", parent)
        })

        fetch("http://localhost:5000/digraph/"+model_name)
        .then( res => res.json())
        .then( json => {

            $("#red-ui-causeway-dialog-export-text").val(json["digraph"])
            // add treatment 


            // select outcome
            console.log("promised response : ",json)
            let treatment = $("#treatment");
            let outcome = $("#outcome");
            nodes.forEach( item=>{
                treatment.append("<option value="+item.name+">"+item.name+"</option>")
                outcome.append("<option value="+item.name+">"+item.name+"</option>")
            })
            $("#red-ui-causeway-dialog-export-text").val(json["digraph"])
        })
        .catch( error=> {console.log("error ", error)})
        .finally( resp=> {console.log("FINALLY ")})
        dialog.dialog("option","title","Causeway Analysis")
        dialog.dialog("open");
    }
    function setUpCausewayDialogs()
    {
        dialog = $('<div id="red-ui-causeway-dialog" class="hide"><form class="dialog-form form-horizontal"></form></div>')
        .appendTo("#red-ui-editor")
        .dialog({
            modal: true,
            autoOpen: false,
            width: 700,
            resizable: false,
            classes: {
                "ui-dialog": "red-ui-editor-dialog",
                "ui-dialog-titlebar-close": "hide",
                "ui-widget-overlay": "red-ui-editor-dialog"
            },
            buttons: [
                { // red-ui-causeway-dialog-cancel
                    id: "red-ui-causeway-dialog-cancel",
                    text: "Cancel",
                    click: function() {
                        $( dialog ).dialog( "close" );
                    }
                },
                {
                    id:"red-ui-causeway-dialog-deploy",
                    text:"Deploy",
                    class:"primary",
                    click:function(){
                        let req_object = {
                            "labels": _labels,
                            "treatment":$("#treatment").val(),
                            "outcome":$("#outcome").val(),
                        }
                        console.log("request data object ", req_object)
                        fetch("http://localhost:5000/graph_data/"+ model_name,{
                            method:"POST",
                            body:JSON.stringify(req_object),
                        }).then( res => res.json())
                          .then(json=>{
                            console.log("RESPONSE from graph_data"+ model_name, json)
                            $("#red-ui-causeway-dialog-export-text-estimate").val(json["estimate"])
                            $("#red-ui-causeway-dialog-export-text-estimand").val(json["identified_estimand"])
                            $("#red-ui-causeway-dialog-export-text-model").val(json["model"])
                        })
                    }
                },
            ],
            open: function( event, ui ) {
                RED.keyboard.disable();
            },
            close: function(e) {
                RED.keyboard.enable();
            }
        });
        dialogContainer = dialog.children(".dialog-form");

        exportCausewayDialog =
            '<div class="form-row">'+
                '<label style="width:auto;margin-right: 10px;">Export</label>'+
                '<span id="red-ui-causeway-dialog-export-rng-group" class="button-group">'+
                    '<a id="red-ui-causeway-dialog-export-rng-flow" class="red-ui-button toggle" href="#"> Current Flow </a>'+
                '</span>'+
            '</div>'+
            '<div class="red-ui-clipboard-dialog-box">'+
                '<div class="red-ui-clipboard-dialog-tabs">'+
                    '<ul id="red-ui-causeway-dialog-export-tabs"></ul>'+
                '</div>'+
                '<div id="red-ui-causeway-dialog-export-tabs-content" class="red-ui-clipboard-dialog-tabs-content">'+
                    '<div id="red-ui-causeway-dialog-export-tab-causeway-clipboard" class="red-ui-clipboard-dialog-tab-clipboard">'+
                        '<div class ="form-row" style="padding:0.25em">'+
                            '<label for = "client-database">Graph</label>' +
                            '<input id="client-database" placeholder = "database name" readonly></input>'+
                        '</div>'+
                        '<div class="form-row" style="height:calc(25%)">'+
                            '<textarea readonly id="red-ui-causeway-dialog-export-text"></textarea>'+
                        '</div>'+
                        '<div class="form-row" >'+
                            '<label for="treatment">Treatment</label>' +
                            '<select  id="treatment"/>'+
                        '</div>'+
                        '<div class="form-row" style="height:calc(50%)">'+
                            '<textarea readonly id="red-ui-causeway-dialog-export-text-estimate"></textarea>'+
                        '</div>'+
                        '<div class="form-row" >'+
                            '<label for="outcome">Outcome</label>' +
                            '<select  id="outcome"/>'+
                        '</div>'+
                        '<div class="form-row" style="height:calc(50%)">'+
                            '<textarea readonly id="red-ui-causeway-dialog-export-text-estimand"></textarea>'+
                        '</div>'+
                        '<div class="form-row" style="height:calc(89%)">'+
                            '<textarea readonly id="red-ui-causeway-dialog-export-text-model"></textarea>'+
                        '</div>'+
                    '</div>'+
                    '<div id="red-ui-causeway-dialog-export-tab-causeway-deploy" class="red-ui-clipboard-dialog-tab-clipboard">'+
                    '</div>'+               
                '</div>'+
            '</div>'
            ;
    }

    function init(options){
        console.log("IN RED CAUSEWAY INIT")
        setUpCausewayDialogs();
        $('<li> <span class = "red-ui-deploy-button-group button-group" >'
        // create the section of the button to implement action 
            +'<a id="red-ui-header-button-causeway-action" class="red-ui-deploy-button disabled" href="#">'
                + '<span class="red-ui-deploy-button-content">' 
                + '<img id="red-ui-header-button-causeway-icon" src="red/images/geminos-logo-17-18.png">'
                +'<span> Causeway </span>'
                + '</span>' 
            +'</a>'
            // create dropdown carret menu
            +'<a id="red-ui-header-button-causeway-options" class="red-ui-deploy-button" href="#"><i class="fa fa-caret-down"></i></a>'
        +'</span></li>').prependTo(".red-ui-header-toolbar");
        // menu initialization
        RED.menu.init({
            id: "red-ui-header-button-causeway-options",
            options:[{
                id: "causeway-deploy",
                icon: "red/images/geminos-logo-17-18.png",
                label:"Causal Analysis",
                sublabel:"Analyze current graph",
                onselect:function(s){ console.log("here", s)}
            },
            ]
        });

        // trigger dialog to pen on click
        $("#red-ui-header-button-causeway-action").on("click", function(event){
            event.preventDefault();
            showCausewayExportDialog()
        })
    }
    return {
        init: init
    }
})();